// Project BD on the Xilinx VC709 (XC7VX690T-2FFG1761): XDMA PCIe Gen2 x8 endpoint
// (AXI-Lite user BAR + one H2C and one C2H AXI-Stream channel, 128 bit at 250 MHz),
// bd_host_if/bd_core on a 79.5 MHz sample clock from an MMCM (playback only in M2;
// the live NT1068 interface comes with M3).
//
// Pins: fpga/vc709/vc709.xdc, taken from the Xilinx VC709 board definition.
// The XDMA IP (module xdma_0) is generated by fpga/vc709/build.tcl.
// NOT YET BUILT OR RUN: written without Vivado; the first build checks the XDMA port
// list and the PCIe block placement (docs/RISKS.md R1, R4).
module vc709_top #(
    parameter integer NCH = 192
) (
    input  wire       pcie_refclk_p,     // 100 MHz from the PCIe edge connector
    input  wire       pcie_refclk_n,
    input  wire       pcie_perst_n,
    output wire [7:0] pcie_txp,
    output wire [7:0] pcie_txn,
    input  wire [7:0] pcie_rxp,
    input  wire [7:0] pcie_rxn,

    input  wire       sysclk_p,          // 200 MHz board oscillator
    input  wire       sysclk_n,

    output wire [7:0] led
);
    // ---------------- PCIe / XDMA ----------------
    wire pcie_refclk;
    IBUFDS_GTE2 u_refclk_buf (.I(pcie_refclk_p), .IB(pcie_refclk_n), .CEB(1'b0),
                              .O(pcie_refclk), .ODIV2());

    wire         aclk, aresetn, link_up;
    wire [31:0]  axil_awaddr, axil_araddr, axil_wdata, axil_rdata;
    wire         axil_awvalid, axil_awready, axil_wvalid, axil_wready, axil_bvalid,
                 axil_bready, axil_arvalid, axil_arready, axil_rvalid, axil_rready;
    wire [1:0]   axil_bresp, axil_rresp;
    wire [127:0] h2c_tdata, c2h_tdata;
    wire [15:0]  h2c_tkeep, c2h_tkeep;
    wire         h2c_tvalid, h2c_tready, h2c_tlast, c2h_tvalid, c2h_tready, c2h_tlast;

    xdma_0 u_xdma (
        .sys_clk(pcie_refclk), .sys_rst_n(pcie_perst_n), .user_lnk_up(link_up),
        .pci_exp_txp(pcie_txp), .pci_exp_txn(pcie_txn),
        .pci_exp_rxp(pcie_rxp), .pci_exp_rxn(pcie_rxn),
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .usr_irq_req(1'b0), .usr_irq_ack(), .msi_enable(), .msi_vector_width(),

        .m_axil_awaddr(axil_awaddr), .m_axil_awprot(), .m_axil_awvalid(axil_awvalid),
        .m_axil_awready(axil_awready), .m_axil_wdata(axil_wdata), .m_axil_wstrb(),
        .m_axil_wvalid(axil_wvalid), .m_axil_wready(axil_wready),
        .m_axil_bvalid(axil_bvalid), .m_axil_bresp(axil_bresp), .m_axil_bready(axil_bready),
        .m_axil_araddr(axil_araddr), .m_axil_arprot(), .m_axil_arvalid(axil_arvalid),
        .m_axil_arready(axil_arready), .m_axil_rdata(axil_rdata), .m_axil_rresp(axil_rresp),
        .m_axil_rvalid(axil_rvalid), .m_axil_rready(axil_rready),

        .m_axis_h2c_tdata_0(h2c_tdata), .m_axis_h2c_tkeep_0(h2c_tkeep),
        .m_axis_h2c_tlast_0(h2c_tlast), .m_axis_h2c_tvalid_0(h2c_tvalid),
        .m_axis_h2c_tready_0(h2c_tready),

        .s_axis_c2h_tdata_0(c2h_tdata), .s_axis_c2h_tkeep_0(c2h_tkeep),
        .s_axis_c2h_tlast_0(c2h_tlast), .s_axis_c2h_tvalid_0(c2h_tvalid),
        .s_axis_c2h_tready_0(c2h_tready)
    );

    // ---------------- sample clock: 200 MHz -> 79.5 MHz ----------------
    // VCO = 200 * 19.875 / 5 = 795 MHz (600-1440 MHz for -2), CLKOUT0 = 795 / 10 = 79.5 MHz.
    wire sysclk, fb, fb_buf, fe_clk_mmcm, fe_clk, mmcm_locked;
    IBUFDS #(.DIFF_TERM("FALSE")) u_sysclk_buf (.I(sysclk_p), .IB(sysclk_n), .O(sysclk));
    MMCME2_BASE #(
        .CLKIN1_PERIOD(5.000), .DIVCLK_DIVIDE(5), .CLKFBOUT_MULT_F(19.875),
        .CLKOUT0_DIVIDE_F(10.000)
    ) u_mmcm (
        .CLKIN1(sysclk), .CLKFBIN(fb_buf), .RST(1'b0), .PWRDWN(1'b0),
        .CLKFBOUT(fb), .CLKFBOUTB(), .CLKOUT0(fe_clk_mmcm), .CLKOUT0B(),
        .CLKOUT1(), .CLKOUT1B(), .CLKOUT2(), .CLKOUT2B(), .CLKOUT3(), .CLKOUT3B(),
        .CLKOUT4(), .CLKOUT5(), .CLKOUT6(), .LOCKED(mmcm_locked)
    );
    BUFG u_fb_buf (.I(fb), .O(fb_buf));
    BUFG u_fe_buf (.I(fe_clk_mmcm), .O(fe_clk));

    // ---------------- Project BD ----------------
    wire pps;
    bd_host_if #(.NCH(NCH), .CODE_AW(14), .W(128)) u_bd (
        .aclk(aclk), .aresetn(aresetn && mmcm_locked),
        .s_axil_awaddr(axil_awaddr[15:0]), .s_axil_awvalid(axil_awvalid),
        .s_axil_awready(axil_awready), .s_axil_wdata(axil_wdata),
        .s_axil_wvalid(axil_wvalid), .s_axil_wready(axil_wready),
        .s_axil_bresp(axil_bresp), .s_axil_bvalid(axil_bvalid), .s_axil_bready(axil_bready),
        .s_axil_araddr(axil_araddr[15:0]), .s_axil_arvalid(axil_arvalid),
        .s_axil_arready(axil_arready), .s_axil_rdata(axil_rdata), .s_axil_rresp(axil_rresp),
        .s_axil_rvalid(axil_rvalid), .s_axil_rready(axil_rready),
        .s_axis_h2c_tdata(h2c_tdata), .s_axis_h2c_tvalid(h2c_tvalid),
        .s_axis_h2c_tready(h2c_tready),
        .m_axis_c2h_tdata(c2h_tdata), .m_axis_c2h_tkeep(c2h_tkeep),
        .m_axis_c2h_tlast(c2h_tlast), .m_axis_c2h_tvalid(c2h_tvalid),
        .m_axis_c2h_tready(c2h_tready),
        .fe_clk(fe_clk), .live_valid(1'b0), .live_sign(4'd0), .live_mag(4'd0),
        .pps_out(pps), .event_in(1'b0)
    );

    // ---------------- bring-up LEDs ----------------
    reg [26:0] beat_a, beat_f;
    always @(posedge aclk)   beat_a <= beat_a + 1'b1;
    always @(posedge fe_clk) beat_f <= beat_f + 1'b1;
    assign led = {4'b0000, pps, beat_f[26], beat_a[26] & link_up, mmcm_locked};

    // h2c_tkeep / h2c_tlast: whole 128-bit beats only (bd_host_if). The AXI-Lite window is
    // 64 KB, so address bits above 15 are always zero.
    wire unused = &{1'b0, h2c_tkeep, h2c_tlast, axil_awaddr[31:16], axil_araddr[31:16]};
endmodule
